export function registerDocksideWindowPasses(objects,lightAnchors){
 for(const object of objects){
  const key=object.sourceAsset,entry=DOCKSIDE_GLASS[key];
  if(!entry)continue;
  CITY_GLASS[key]=entry;
  lightAnchors[key]=entry.windows.map(window=>window.anchor);
 }
}
